package com.mobileuse.galaxy;
import android.app.*;import android.content.*;import android.media.projection.*;import android.os.*;import android.provider.Settings;import android.graphics.Color;import android.widget.*;
public final class MainActivity extends Activity {
 private static final int CAPTURE_REQUEST=140;private final Handler statusHandler=new Handler(Looper.getMainLooper());private final Runnable statusTicker=new Runnable(){public void run(){if(status!=null)refresh();statusHandler.postDelayed(this,800);}};private TextView status;private TextView localStatus;private TextView companyStatus;private static final int EXPORT_REQUEST=141;private EditText task,key;private CheckBox sendImages;private android.content.SharedPreferences prefs;
 @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("local_progress",MODE_PRIVATE);ScrollView scroll=new ScrollView(this);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(28,30,28,28);scroll.addView(root);
 TextView title=new TextView(this);title.setText("Mobile Use · Z Fold8 v2.0");title.setTextSize(23);root.addView(title);status=new TextView(this);root.addView(status);
 button(root,"1. 접근성 서비스 켜기",()->startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS)));
 button(root,"2. 화면 캡처 승인",()->{MediaProjectionManager mgr=getSystemService(MediaProjectionManager.class);startActivityForResult(mgr.createScreenCaptureIntent(),CAPTURE_REQUEST);});
 task=new EditText(this);task.setHint("작업 목표 (로그인·결제·송금 금지)");task.setText(prefs.getString("task",""));root.addView(task);
 key=new EditText(this);localStatus=new TextView(this);root.addView(localStatus);button(root,"Gemma .litertlm 모델 가져오기",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*");startActivityForResult(i,142);});button(root,"GPU 모델 초기화",()->LocalEngine.initialize(this));button(root,"GPU 메모리 해제",()->{TaskRunner.stop();LocalEngine.release();});
 sendImages=new CheckBox(this);sendImages.setText("화면 이미지를 OpenAI로 전송 (개인정보 포함 가능, 명시적 동의)");sendImages.setChecked(false);sendImages.setEnabled(false);root.addView(sendImages);
 CheckBox external=new CheckBox(this);external.setText("삼성 설정 화면 읽기·스크롤 허용 (클릭 금지)");external.setChecked(false);prefs.edit().putBoolean("allow_settings_read",false).apply();external.setOnCheckedChangeListener((v,checked)->prefs.edit().putBoolean("allow_settings_read",checked).apply());root.addView(external);CheckBox continuous=new CheckBox(this);continuous.setText("연속 실행 (최대 20단계 / 120초)");root.addView(continuous);button(root,"내장 테스트 화면 열기",()->startActivity(new Intent(this,SandboxActivity.class)));button(root,"3. 플로팅 컨트롤러 준비",()->{String t=task.getText().toString();if(!ActionPolicy.safeTask(t)){status.setText("민감하거나 유효하지 않은 작업");return;}prefs.edit().putString("task",t).putInt("step",0).remove("last_error").apply();if(!LocalEngine.isReady()){status.setText("GPU 모델을 먼저 초기화하세요");return;}TaskRunner.setContinuous(continuous.isChecked());TaskRunner.prepare(key.getText().toString(),t,false);status.setText("준비 완료. 내장 테스트 또는 허용된 설정 화면에서 작업 실행을 누르세요.");});
 TextView companyTitle=new TextView(this);companyTitle.setText("공개 기업정보 자동 수집 (OpenDART)");companyTitle.setTextSize(20);root.addView(companyTitle);
 EditText dartKey=new EditText(this);dartKey.setHint("OpenDART 인증키 (40자리)");dartKey.setInputType(129);dartKey.setSaveEnabled(false);root.addView(dartKey);
 EditText codes=new EditText(this);codes.setHint("DART 고유번호 8자리, 쉼표 구분 (최대 30개)");root.addView(codes);
 EditText year=new EditText(this);year.setHint("사업보고서 기준연도");year.setInputType(2);year.setText("2025");root.addView(year);
 companyStatus=new TextView(this);root.addView(companyStatus);
 button(root,"기업정보 수집 시작 / 동일 목록 이어서",()->{if(TaskRunner.isRunning()){companyStatus.setText("AI 작업을 먼저 중지하세요");return;}boolean ok=CompanyCollector.start(this,dartKey.getText().toString().trim(),codes.getText().toString().trim(),year.getText().toString().trim());if(!ok)companyStatus.setText("인증키·고유번호·연도 또는 실행 상태 확인");});
 button(root,"기업정보 수집 중지",()->CompanyCollector.stop());
 button(root,"CSV 파일 저장",()->{if(CompanyCollector.isRunning()){companyStatus.setText("수집 완료 또는 중지 후 저장하세요");return;}if(!new java.io.File(getFilesDir(),"companies.csv").exists()){companyStatus.setText("저장할 수집 결과가 없습니다");return;}Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("text/csv").putExtra(Intent.EXTRA_TITLE,"companies.csv");startActivityForResult(i,EXPORT_REQUEST);});
 button(root,"작업 결과 공유",()->{Intent share=new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,prefs.getString("live_log","기록 없음"));startActivity(Intent.createChooser(share,"작업 로그 공유"));});button(root,"현재 화면 접근성 텍스트 확인",()->{String v=ControlService.inspect();status.setText(v.isEmpty()?"현재 화면에서 읽을 수 있는 텍스트가 없습니다":v);});
 Button stop=new Button(this);stop.setText("긴급 정지");stop.setTextColor(Color.WHITE);stop.setBackgroundTintList(android.content.res.ColorStateList.valueOf(Color.RED));stop.setOnClickListener(v->{CompanyCollector.stop();TaskRunner.stop();startService(new Intent(this,CaptureService.class).setAction(CaptureService.ACTION_STOP_ALL));refresh();});root.addView(stop);
 TextView note=new TextView(this);note.setText("주의: 접근성 텍스트에도 개인정보가 포함될 수 있습니다. 화면 이미지 전송은 기본 꺼짐이며, 키는 저장하지 않습니다. 화면 분석 중 금융·로그인·인증 화면이 감지되면 중단합니다. 긴급 정지는 캡처 알림에서도 실행할 수 있습니다. v2.0은 실기기 미검증 개발 빌드입니다.");root.addView(note);setContentView(scroll);refresh();statusHandler.postDelayed(statusTicker,800);}
 private void button(LinearLayout root,String label,Runnable r){Button b=new Button(this);b.setText(label);b.setOnClickListener(v->r.run());root.addView(b);}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==142&&result==RESULT_OK&&data!=null&&data.getData()!=null){LocalEngine.importModel(this,data.getData());return;}if(request==EXPORT_REQUEST&&result==RESULT_OK&&data!=null&&data.getData()!=null){try{CompanyCollector.export(this,data.getData());Toast.makeText(this,"CSV 저장 완료",Toast.LENGTH_LONG).show();}catch(Exception e){Toast.makeText(this,"CSV 저장 실패",Toast.LENGTH_LONG).show();}return;}if(request==CAPTURE_REQUEST&&result==RESULT_OK&&data!=null){Intent i=new Intent(this,CaptureService.class).setAction(CaptureService.START).putExtra("resultCode",result).putExtra("data",data);startForegroundService(i);status.setText("화면 캡처 승인됨");}}
 private void refresh(){if(localStatus!=null)localStatus.setText("로컬 AI: "+LocalEngine.status());if(companyStatus!=null)companyStatus.setText("기업 수집: "+CompanyCollector.status());status.setText("접근성: "+(ControlService.active==null?"꺼짐":"켜짐")+" | 캡처: "+(CaptureService.instance==null?"꺼짐":"서비스 실행")+" | AI: "+(TaskRunner.isRunning()?"실행 중":"대기")+" | 단계: "+prefs.getInt("step",0)+" | 마지막 행동: "+prefs.getString("last_action","없음")+" | 오류: "+prefs.getString("last_error","없음"));}
 @Override protected void onDestroy(){statusHandler.removeCallbacks(statusTicker);super.onDestroy();}
 @Override protected void onResume(){super.onResume();if(status!=null)refresh();}
}
